(6348386, 939683, 93283, '<td valign="top">I simply love this shot! Masterfully done and a perfect 10</td>', 'I simply love this shot! Masterfully done and a perfect 10', '2011-03-11 00:34:58.000000', NULL, 1),
(6348387, 939910, 93283, '<td valign="top">The composition of this photograph is what really stands out. The person in the center sets it off, its a perfect 10... and a fav... Well Done!</td>', 'The composition of this photograph is what really stands out. The person in the center sets it off, its a perfect 10... and a fav... Well Done!', '2011-03-11 00:35:45.000000', NULL, 1),
(6348388, 940057, 93283, '<td valign="top">The stillness of this photo to me is the icing on the cake. Beautiful image that leaves you breathless. 10</td>', 'The stillness of this photo to me is the icing on the cake. Beautiful image that leaves you breathless. 10', '2011-03-11 00:36:19.000000', NULL, 1),
(6348392, 940063, 54446, '<td valign="top">Peak 9 at Breck?</td>', 'Peak 9 at Breck?', '2011-03-11 00:48:59.000000', NULL, 1),
(6348403, 939854, 54446, '<td valign="top">Nice car light trails.  And, the street lights tell us it was dark enough.</td>', 'Nice car light trails.  And, the street lights tell us it was dark enough.', '2011-03-11 01:13:42.000000', NULL, 1),
(6348404, 939266, 54446, '<td valign="top">Excellent rural scene.  Superb exposure.  The star trails are a good element of interest.</td>', 'Excellent rural scene.  Superb exposure.  The star trails are a good element of interest.', '2011-03-11 01:14:51.000000', NULL, 1),
(6348410, 939683, 76712, '<td valign="top">Holy crap........i think i have a new all time favourite.</td>', 'Holy crap........i think i have a new all time favourite.', '2011-03-11 01:18:16.000000', NULL, 1),
(6348419, 940056, 54446, '<td valign="top">A very cool image.  Looks like day to me, yet the star trails tell us this is night.  Cool colors above and warm colors on the ground.... a difficult task, well executed.  Meets the challenge especially well.  The light globe emulates the sun especially well.  Nicely done!</td>', 'A very cool image.  Looks like day to me, yet the star trails tell us this is night.  Cool colors above and warm colors on the ground.... a difficult task, well executed.  Meets the challenge especially well.  The light globe emulates the sun especially well.  Nicely done!', '2011-03-11 01:25:14.000000', NULL, 1),
(6348425, 939148, 54446, '<td valign="top">Superb b&amp;w conversion.  Magical light.  The scene looks almost day-like.  My top pick in this challenge, based on technical excellence and composition.</td>', 'Superb b&w conversion.  Magical light.  The scene looks almost day-like.  My top pick in this challenge, based on technical excellence and composition.', '2011-03-11 01:28:14.000000', NULL, 1),
