(6348983, 940071, 121949, '<td valign="top">The best of the challenge, I think we will be seeing two ribbons from you this week.</td>', 'The best of the challenge, I think we will be seeing two ribbons from you this week.', '2011-03-11 18:19:08.000000', NULL, 1),
