(6349005, 939821, 54446, '<td valign="top">Great job on the even exposure.</td>', 'Great job on the even exposure.', '2011-03-11 18:58:17.000000', NULL, 1),
(6349029, 939952, 3102, '<td valign="top">Very impressive -- my favorite of the bunch!  This really does a great job of doing what the challenge suggested -- looking like daylight while keeping elements of night.  I expect to see a ribbon on this one.</td>', 'Very impressive -- my favorite of the bunch!  This really does a great job of doing what the challenge suggested -- looking like daylight while keeping elements of night.  I expect to see a ribbon on this one.', '2011-03-11 19:37:38.000000', NULL, 1),
(6349034, 940084, 3102, '<td valign="top">Very nice -- one of my favorites!</td>', 'Very nice -- one of my favorites!', '2011-03-11 19:39:51.000000', NULL, 1),
